import re,os,json
def parse(name,text):
    m=re.search(name+r' \((\d+)x(\d+)\):\n',text)
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in text[m.end():].split('\n')[i].split()] for i in range(h)]
t=open(os.environ['RLM_SESSION_DIR']+'/../../sessions/'+os.path.basename(os.environ['RLM_SESSION_DIR'])+'.jsonl').read().replace('\\n','\n')
di=parse('Demo pair 1 input',t); do=parse('Demo pair 1 output',t)
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            nb=[g[y][x] for y,x in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=y<h and 0<=x<w]
            if g[i][j] not in nb:
                out[i][j]=max(set(nb),key=nb.count)
    return out
